<script setup lang="ts">
import { computed, ref } from 'vue'
const dataset=ref('A')
const hold=ref('column')
const selected=ref(0)
const state=ref('ready')
const labels=['Jan','Feb','Mar','Apr','May','Jun']
const primary=computed(()=>dataset.value==='A'?[35,48,41,61,56,74]:dataset.value==='B'?[42,36,55,48,72,64]:[0,0,0,0,0,0])
const x=(i:number)=>40+i*48
const y=(v:number)=>170-v*1.4
function reset(){dataset.value='A';hold.value='column';selected.value=0;state.value='ready'}
</script>
<template>
<section class="barusage-chart-demo" aria-label="Local bar chart example"><p>Synthetic monthly units. Bar length measures magnitude from zero. Switch orientation without changing observations.</p><div class="barusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="zero">All zero</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><label>Orientation<select v-model="hold"><option value="column">Columns</option><option value="row">Rows</option></select></label><button type="button" @click="reset">Reset example</button></div><template v-if="state==='ready'"><div class="barusage-legend"><span>Single series: Primary units</span><span>{{ hold==='column'?'Columns rise from zero':'Rows extend from zero' }}</span></div><svg :key="dataset+'-'+hold" viewBox="0 0 320 210" role="img" aria-label="Synthetic monthly units, January to June, fixed scale 0 to 100. Bars start at zero; exact values are in the table below."><template v-if="hold==='column'"><g v-for="tick in [0,25,50,75,100]" :key="tick"><line x1="36" x2="292" :y1="y(tick)" :y2="y(tick)" class="barusage-grid"/><text x="4" :y="y(tick)+4">{{ tick }}</text></g><g v-for="(v,i) in primary" :key="i"><rect class="barusage-mark" :class="{selected:selected===i}" :x="x(i)-10" :y="y(v)" width="20" :height="v*1.4"/><circle v-if="v===0" :cx="x(i)" cy="170" r="2" class="barusage-zero"/><text :x="x(i)" y="194" text-anchor="middle">{{ labels[i] }}</text></g></template><template v-else><g v-for="tick in [0,25,50,75,100]" :key="tick"><line :x1="50+tick*2.3" :x2="50+tick*2.3" y1="18" y2="174" class="barusage-grid"/><text :x="50+tick*2.3" y="194" text-anchor="middle">{{ tick }}</text></g><g v-for="(v,i) in primary" :key="i"><text x="4" :y="32+i*26">{{ labels[i] }}</text><rect class="barusage-mark" :class="{selected:selected===i}" x="50" :y="20+i*26" :width="v*2.3" height="16"/><circle v-if="v===0" cx="50" :cy="28+i*26" r="2" class="barusage-zero"/></g></template></svg><div role="group" aria-label="Select month" class="barusage-months"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @click="selected=i" @focus="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: Primary {{ primary[selected] }} units.</p><table class="barusage-data"><caption>Exact sample values, dataset {{ dataset }}</caption><thead><tr><th scope="col">Month</th><th scope="col">Primary units</th></tr></thead><tbody><tr v-for="(label,i) in labels" :key="label"><th scope="row">{{ label }}</th><td>{{ primary[i] }}</td></tr></tbody></table></template><p v-else role="status" class="barusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Values are withheld.':'No sample observations in this state. Choose Ready to recover.' }}</p></section>
</template>
<style scoped>
.barusage-chart-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.barusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.barusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.barusage-chart-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.barusage-chart-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.barusage-chart-demo :is(button,select,input):focus-visible{outline:2px solid var(--vp-c-brand-1);outbarusage-offset:3px}.barusage-legend{display:flex;gap:16px;flex-wrap:wrap;margin-top:18px;font-size:12px}.barusage-chart-demo svg{display:block;width:100%;height:auto;max-height:330px;margin:16px 0;animation:barusage-chart-in .2s ease-out}.barusage-grid{stroke:var(--vp-c-divider);stroke-dasharray:3 4}.barusage-chart-demo svg text{fill:var(--vp-c-text-2);font-size:10px}.barusage-mark{fill:var(--vp-c-brand-1);fill-opacity:.6;stroke:var(--vp-c-brand-1);stroke-width:1}.barusage-mark.selected{fill-opacity:1;stroke:var(--vp-c-text-1);stroke-width:2}.barusage-zero{fill:var(--vp-c-text-1)}.barusage-dot{fill:var(--vp-c-brand-1);stroke:var(--vp-c-bg);stroke-width:1}.barusage-months{display:flex;gap:6px;flex-wrap:wrap}.barusage-months button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.barusage-data{display:table!important;width:100%;font-size:12px}.barusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.barusage-data :is(td,th){padding:6px 8px!important}.barusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}@keyframes barusage-chart-in{from{opacity:.4}to{opacity:1}}@media(prefers-reduced-motion:reduce){.barusage-chart-demo svg{animation:none}}
</style>
